from __future__ import annotations

import importlib
import traceback
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _clamp01(v: Any, default: float = 0.0) -> float:
    try:
        x = float(v)
        if x > 1.0 and x <= 100.0:
            x = x / 100.0
        return max(0.0, min(1.0, x))
    except Exception:
        return default


@dataclass
class ProviderResult:
    name: str
    available: bool
    score: float = 0.0
    label: str = "unknown"
    reason: str = ""
    raw: Any = None
    error: Optional[str] = None


@dataclass
class QualityReport:
    asset_path: str
    final_score: float
    grade: str
    passed: bool
    provider_count: int
    available_count: int
    weights: Dict[str, float]
    details: List[ProviderResult] = field(default_factory=list)
    suggestions: List[str] = field(default_factory=list)
    created_at: str = field(default_factory=_now)

    def to_dict(self) -> Dict[str, Any]:
        data = asdict(self)
        data["details"] = [asdict(x) for x in self.details]
        return data

    def to_markdown(self) -> str:
        rows = []
        for item in self.details:
            status = "可用" if item.available else "不可用"
            rows.append(
                f"| {item.name} | {status} | {item.score:.3f} | "
                f"{item.label} | {item.reason or item.error or '-'} |"
            )
        suggestions = "\n".join(f"- {x}" for x in self.suggestions) or "- 暂无"
        return f"""# 素材质量报告

- 素材：`{self.asset_path}`
- 综合得分：**{self.final_score:.3f}**
- 等级：**{self.grade}**
- 结论：**{"通过" if self.passed else "需复查"}**
- 可用Provider：{self.available_count}/{self.provider_count}
- 生成时间：{self.created_at}

## Provider明细

| Provider | 状态 | 得分 | 标签 | 说明 |
|---|---|---:|---|---|
{chr(10).join(rows)}

## 建议

{suggestions}
"""


class ProviderAdapter:
    def __init__(self, name: str, provider: Any, weight: float):
        self.name = name
        self.provider = provider
        self.weight = weight

    def run(self, asset_path: str, **kwargs: Any) -> ProviderResult:
        if self.provider is None:
            return ProviderResult(self.name, False, error="provider not loaded")
        try:
            raw = self._call(asset_path, **kwargs)
            score, label, reason = self._normalize(raw)
            return ProviderResult(
                name=self.name,
                available=True,
                score=score,
                label=label,
                reason=reason,
                raw=raw,
            )
        except Exception as exc:
            return ProviderResult(
                name=self.name,
                available=False,
                error=f"{type(exc).__name__}: {exc}",
                raw=traceback.format_exc(limit=3),
            )

    def _call(self, asset_path: str, **kwargs: Any) -> Any:
        for method_name in ("evaluate", "assess", "analyze", "predict", "score", "run"):
            fn = getattr(self.provider, method_name, None)
            if not callable(fn):
                continue
            try:
                return fn(asset_path, **kwargs)
            except TypeError:
                try:
                    return fn(asset_path)
                except TypeError:
                    return fn({"path": asset_path, **kwargs})
        if callable(self.provider):
            return self.provider(asset_path, **kwargs)
        raise RuntimeError("no callable method found")

    def _normalize(self, raw: Any) -> Tuple[float, str, str]:
        if isinstance(raw, (int, float)):
            return _clamp01(raw), "score", ""
        if not isinstance(raw, dict):
            return 0.0, "unknown", str(raw)[:200]

        score_keys = ("score", "quality_score", "final_score", "vqa_score", "confidence", "prob")
        score = 0.0
        for key in score_keys:
            if key in raw:
                score = _clamp01(raw.get(key))
                break

        if score == 0.0 and isinstance(raw.get("scores"), dict):
            vals = [_clamp01(v) for v in raw["scores"].values()]
            score = sum(vals) / len(vals) if vals else 0.0

        label = str(raw.get("label") or raw.get("grade") or raw.get("quality") or "unknown")
        reason = str(raw.get("reason") or raw.get("message") or raw.get("summary") or "")
        return score, label, reason


class VQAFusion:
    DEFAULT_WEIGHTS = {"cover": 0.5, "rq_vqa": 0.3, "relax_vqa": 0.2}
    DEFAULT_PROVIDERS = {
        "cover": ("phs.providers.vqa.cover", ("COVERProvider", "CoverProvider", "Provider")),
        "rq_vqa": ("phs.providers.vqa.rq_vqa", ("RQVQAProvider", "RQVQA", "Provider")),
        "relax_vqa": ("phs.providers.vqa.relax_vqa", ("ReLaXVQAProvider", "RelaxVQAProvider", "Provider")),
    }

    def __init__(
        self,
        providers: Optional[Dict[str, Any]] = None,
        weights: Optional[Dict[str, float]] = None,
        pass_threshold: float = 0.65,
    ):
        self.weights = dict(self.DEFAULT_WEIGHTS)
        if weights:
            self.weights.update(weights)
        self.pass_threshold = pass_threshold
        self.adapters: Dict[str, ProviderAdapter] = {}

        loaded = providers if providers is not None else self._load_default_providers()
        for name, weight in self.weights.items():
            self.adapters[name] = ProviderAdapter(name, loaded.get(name), weight)

    def _load_default_providers(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for name, (module_name, class_names) in self.DEFAULT_PROVIDERS.items():
            result[name] = self._try_load(module_name, class_names)
        return result

    @staticmethod
    def _try_load(module_name: str, class_names: Tuple[str, ...]) -> Any:
        try:
            mod = importlib.import_module(module_name)
            for cls_name in class_names:
                cls = getattr(mod, cls_name, None)
                if cls:
                    return cls()
            create_provider = getattr(mod, "create_provider", None)
            if callable(create_provider):
                return create_provider()
            provider = getattr(mod, "provider", None)
            if provider is not None:
                return provider
        except Exception:
            return None
        return None

    def evaluate(self, asset_path: str, **kwargs: Any) -> QualityReport:
        details = [adapter.run(asset_path, **kwargs) for adapter in self.adapters.values()]
        available = [x for x in details if x.available]
        final_score = self._weighted_score(available)
        grade = self._grade(final_score, len(available))
        suggestions = self._suggestions(final_score, details)

        return QualityReport(
            asset_path=str(asset_path),
            final_score=round(final_score, 4),
            grade=grade,
            passed=bool(available) and final_score >= self.pass_threshold,
            provider_count=len(details),
            available_count=len(available),
            weights=dict(self.weights),
            details=details,
            suggestions=suggestions,
        )

    def _weighted_score(self, results: List[ProviderResult]) -> float:
        total_weight = 0.0
        total_score = 0.0
        for item in results:
            w = float(self.weights.get(item.name, 0.0))
            total_weight += w
            total_score += item.score * w
        return total_score / total_weight if total_weight else 0.0

    @staticmethod
    def _grade(score: float, available_count: int) -> str:
        if available_count == 0:
            return "unavailable"
        if score >= 0.85:
            return "excellent"
        if score >= 0.70:
            return "good"
        if score >= 0.55:
            return "warning"
        return "poor"

    @staticmethod
    def _suggestions(score: float, details: List[ProviderResult]) -> List[str]:
        tips: List[str] = []
        if not any(x.available for x in details):
            return ["三个VQA Provider均不可用，请检查 phs/providers/vqa/ 封装与模型路径。"]
        for item in details:
            if not item.available:
                tips.append(f"{item.name} 不可用，已自动降级融合。")
        if score < 0.55:
            tips.append("素材质量偏低，建议更换封面、提升清晰度或减少遮挡/水印。")
        elif score < 0.70:
            tips.append("素材质量一般，建议进入人工复核或生成变体后重评。")
        else:
            tips.append("素材质量达标，可进入后续去重、变体或Loop编译流程。")
        return tips


class BatchProcessor:
    def __init__(self, fusion: Optional[VQAFusion] = None):
        self.fusion = fusion or VQAFusion()

    def process(self, asset_paths: List[str], **kwargs: Any) -> List[Dict[str, Any]]:
        return [self.fusion.evaluate(path, **kwargs).to_dict() for path in asset_paths]

    def process_dir(
        self,
        directory: str,
        suffixes: Tuple[str, ...] = (".jpg", ".jpeg", ".png", ".webp", ".mp4", ".mov"),
        **kwargs: Any,
    ) -> List[Dict[str, Any]]:
        root = Path(directory)
        files = [str(p) for p in root.rglob("*") if p.is_file() and p.suffix.lower() in suffixes]
        return self.process(files, **kwargs)

    def summary(self, reports: List[Dict[str, Any]]) -> Dict[str, Any]:
        total = len(reports)
        passed = sum(1 for x in reports if x.get("passed"))
        avg = sum(float(x.get("final_score", 0.0)) for x in reports) / total if total else 0.0
        grades: Dict[str, int] = {}
        for item in reports:
            grades[item.get("grade", "unknown")] = grades.get(item.get("grade", "unknown"), 0) + 1
        return {"total": total, "passed": passed, "failed": total - passed, "avg_score": round(avg, 4), "grades": grades}


__all__ = ["ProviderResult", "QualityReport", "VQAFusion", "BatchProcessor"]
